export const SPEED_TIER_VALUES: readonly SpeedTier[] = [
  "very_fast",
  "fast",
  "medium",
  "slow",
  "very_slow",
  "unknown",
] as const;

export interface ModelMeta {
  coverage?: string[];
  useCases?: string[];
  properties?: PropertyTag[];
  frameworks?: FrameworkTag[];
  license?: string;
  maintenance?: MaintenanceStatus;
  lastReviewed?: string | "unknown";
  lastUpdated?: string;
  trainingData?: string[];
  tags?: string[];
  // Whether the model can be conditioned on a total/atomic charge. `null`
  // (or an absent value) means the curators have not yet verified this.
  supportsCharges?: boolean | null;
  // Whether the model can be conditioned on spin multiplicity / magnetic
  // moments. `null` (or absent) means unknown.
  supportsSpins?: boolean | null;
  // Free-form description of the elemental coverage. Examples:
  //   "H, C, N, O"           — explicit element list
  //   "all elements up to Z=94" — bulk-coverage shorthand
  //   "—"                    — explicitly recorded as unknown / not applicable
  // For new entries one of: an explicit list, a coverage shorthand, or "—".
  elementsCovered?: string | null;

  // Multi-axis tag fields driving the new filter UI. All `null` by default;
  // the curators populate as papers are audited. Filter excludes `null`s
  // when the corresponding axis has any active value.
  // - "constrained": strict E(3)/SO(3) equivariance baked into the architecture
  //   (NequIP, MACE, Allegro, Equiformer).
  // - "learnt": rotation-invariance achieved via data augmentation or relaxed
  //   equivariance (Orb-style).
  // - "invariant": only invariant features (SchNet, DimeNet, BPNN-style).
  equivariance?: Equivariance | null;
  // - "descriptor": hand-crafted features + regression / fully-connected NN
  //   (BPNN, GAP, ACE, ANI, NEP).
  // - "gnn": graph / message-passing.
  architecture?: Architecture | null;
  // Whether the architecture is attention-based.
  usesAttention?: boolean | null;
  // Whether the model explicitly handles long-range / Ewald / electrostatics.
  longRange?: boolean | null;
  // Approximate number of training examples (rough order of magnitude is fine).
  trainingSetSize?: number | null;
  // Integer count of elements covered (parallel to the free-form
  // `elementsCovered` so a numeric slider can use it).
  numElements?: number | null;

  // --- Verification / provenance (Phase 1) ---------------------------------
  // All optional and backward-compatible. Absence means "not yet audited":
  // `effectiveVerificationStatus` resolves an absent value to "needs_review",
  // so nothing is ever silently treated as verified. Do not set
  // `verificationStatus: "verified"` without populating `verifiedSources`.
  verificationStatus?: VerificationStatus;
  // URLs / DOIs that were actually checked while verifying this entry.
  verifiedSources?: string[];
  // ISO date (YYYY-MM-DD) of the last verification pass, or null if never.
  lastVerifiedDate?: string | null;
  verifiedBy?: VerifiedBy;
  // Free-form curator notes about what was (or still needs to be) checked.
  evidenceNotes?: string;

  // Claim-level evidence (free-form citation / note backing a specific claim).
  // TODO(curators): populate as individual claims are audited; absence means
  // the claim has not been independently sourced yet.
  speedEvidence?: string;
  accuracyEvidence?: string;
  datasetEvidence?: string;
  foundationModelEvidence?: string;
  chargeSpinEvidence?: string;
  licenseEvidence?: string;

  // --- Identity & capability axes (Phase 2) --------------------------------
  // Distinguishes architectures from pretrained model instances so that e.g.
  // base MACE (architecture) is never conflated with MACE-MP-0 (foundation
  // model). All optional; absent = not yet classified.
  entityType?: EntityType;
  // Architecture family this entry belongs to (e.g. "MACE", "SevenNet").
  architectureFamily?: string;
  trainingScope?: TrainingScope;
  // Whether this entry itself is a pretrained foundation model. Setting
  // `true` requires foundationModelEvidence (validator-enforced).
  isFoundationModel?: TriState;
  // Whether a foundation-style pretrained variant exists in this entry's
  // family (true for the foundation entries themselves).
  hasFoundationVariant?: TriState;
  // Separate cost / speed / accuracy axes — never combine into one label, and
  // never set a non-"unknown" tier without the matching evidence field.
  inferenceCost?: InferenceCost;
  speedTier?: SpeedTier;
  accuracyTier?: AccuracyTier;
  // Which benchmark/setting any tier claims refer to.
  benchmarkContext?: string;

  // --- Capability flags (Phase 3 filters) ----------------------------------
  // Tri-state (boolean | "unknown"); absent = not yet reviewed. Filters treat
  // only an explicit `true`/`false` as a match — "unknown" and absent are
  // never coerced to false.
  hasDenoisingPretraining?: TriState;
  hasMultipleHeads?: TriState;
  hasMultipleExperts?: TriState; // mixture-of-experts (MoE)
  hasUncertaintyEstimates?: TriState;
  // Normalized, registry-linked training datasets. Kept SEPARATE from the
  // free-form `trainingData` provenance text. Phase 4 populates these together
  // with a dataset registry (stable ids + aliases). Absent = not yet
  // normalized — do not infer from `trainingData`.
  trainedDatasets?: string[];
}

export interface BaseNode {
  id: string;
  type: NodeType;
}

export interface GroupNode extends BaseNode {
  type: "group";
  label: string;
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface ModelNode extends BaseNode, ModelMeta {
  type: "node";
  category: Category;
  label: string;
  year: number;
  author: string;
  x: number;
  y: number;
  desc: string;
  isNew?: boolean;
  dimmed?: boolean;
  githubUrl?: string;
  paperUrl?: string;
}

// Resolve the curation status the UI should display. An absent
// `verificationStatus` is deliberately treated as "needs_review" — never
// "verified" — so un-curated entries are never presented as authoritative.
// Single source of truth for both the explorer detail panel and the table.
export function effectiveVerificationStatus(
  node: Pick<ModelMeta, "verificationStatus">,
): VerificationStatus {
  return node.verificationStatus ?? "needs_review";
}

