    x: 6820,
    y: 320,
    desc:
      "Node-equivariant message-passing graph neural network that reformulates equivariant message passing from edges to nodes: rather than computing a tensor product between every edge and its neighbour node, NEMP constructs an expressive equivariant structure via a single tensor product between the central node and a virtual summed node encoding its neighbours. This reduces the cost of the equivariant message-passing step from the number of neighbour pairs to the number of central atoms, achieving 1–2 orders of magnitude reduction in memory and compute over edge-equivariant baselines while matching or exceeding accuracy across molecules, extended systems, and universal-potential benchmarks. Published in Chemical Science (RSC, 2026).",
